package org.example;

import com.jme3.asset.AssetManager;
import com.jme3.scene.Spatial;
import com.jme3.system.JmeSystem;
import org.junit.Test;

import static org.junit.Assert.*;

public class AppTest {
    /**
     * Loads the model the same way {@link Main} does, headlessly,
     * to make sure the asset path and the loaders are correct.
     */
    @Test public void carModelIsLoadable() {
        AssetManager assetManager =
                JmeSystem.newAssetManager(JmeSystem.getPlatformAssetConfigURL());
        Spatial car = assetManager.loadModel("Models/ferrari_f1_2019_jme.glb");
        assertNotNull("car model should be loadable", car);
        if (car instanceof com.jme3.scene.Node) {
            assertFalse("car model should contain geometry",
                    ((com.jme3.scene.Node) car).getChildren().isEmpty());
        }
    }
}
